      content: "/* =================================================================\n   Inside-POV 3D Carousel — the viewer stands at the center of a\n   ring and looks outward at cards placed on the circumference.\n   ================================================================= */\n\n.carousel {\n  position: relative;\n  width: 100%;\n  height: min(74vh, 680px);\n  min-height: 480px;\n  display: grid;\n  place-items: center;\n  overflow: hidden;\n  isolation: isolate;\n  user-select: none;\n  touch-action: none;\n  cursor: grab;\n  outline: none;\n  background: transparent;\n\n  /* --- Main tuning variables (desktop baseline: 7 visible cards with\n     strong Z-depth). Small perspective + large radius makes the center\n     card recede and the side cards advance toward the camera. All are\n     vw-linked so the 7-card clipping ratio holds across widths.\n     ≈1440px resolves to perspective≈890 / radius≈850. Explicit props\n     override these via inline CSS variables on the root element. --- */\n  --pov-perspective: clamp(760px, 62vw, 1400px); /* smaller = stronger depth */\n  --pov-radius: clamp(680px, 59vw, 1500px);      /* larger = wider Z spread */\n  --pov-card-w: clamp(290px, 23.5vw, 450px);\n  --pov-card-h: calc(var(--pov-card-w) * 1.7);\n  --pov-step: 25.714285deg; /* per-card angle; JS overrides to 360/count */\n  --pov-rotation: 0deg;     /* current rotation; JS updates every frame */\n  --pov-tilt-x: 0deg;\n  --pov-card-radius: 18px;\n  --pov-shift-y: 0px;       /* vertical offset (reserves room for the hint) */\n  /* Drag-hint offset below center. Tuned for the clamp() card size above;\n     overridden via inline style whenever cardWidth is passed explicitly\n     (see the geometry effect in InsidePovCarousel.tsx). */\n  --pov-hint-offset: 240px;\n}\n\n/* ------------------------------------------------------------------\n   3D stage (viewpoint = center of perspective-origin)\n   ------------------------------------------------------------------ */\n.stage {\n  position: absolute;\n  inset: 0;\n  display: grid;\n  place-items: center;\n  perspective: var(--pov-perspective);\n  perspective-origin: 50% 50%;\n  overflow: hidden;\n  transform-style: preserve-3d;\n}\n\n.world {\n  position: relative;\n  width: 0;\n  height: 0;\n  transform-style: preserve-3d;\n  transform: translateY(var(--pov-shift-y)) rotateX(var(--pov-tilt-x))\n    rotateY(var(--pov-rotation));\n  will-change: transform;\n}\n\n/* ------------------------------------------------------------------\n   Cards on the ring (negative translateZ pushes them outward, so the\n   card facing the camera is the farthest — the tunnel-depth effect)\n   ------------------------------------------------------------------ */\n.card {\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  width: var(--pov-card-w);\n  height: var(--pov-card-h);\n  margin: 0;\n  overflow: hidden;\n  border-radius: var(--pov-card-radius);\n  /* Hidden until media is ready — no gray placeholder flash. */\n  background: transparent;\n  opacity: 0;\n  transition: opacity 0.5s ease;\n  transform-style: preserve-3d;\n  transform:\n    translate(-50%, -50%)\n    rotateY(calc(var(--i) * var(--pov-step)))\n    translateZ(calc(var(--pov-radius) * -1));\n  box-shadow: none;\n  backface-visibility: hidden;\n  -webkit-backface-visibility: hidden;\n  will-change: transform;\n}\n\n.card.isLoaded {\n  opacity: 1;\n}\n\n/* Inner highlight + lower shading for dimensionality */\n.card::before {\n  content: \"\";\n  position: absolute;\n  inset: 0;\n  z-index: 3;\n  border-radius: inherit;\n  box-shadow:\n    inset 0 0 0 1px rgba(255, 255, 255, 0.36),\n    inset 0 22px 36px rgba(255, 255, 255, 0.14),\n    inset 0 -38px 58px rgba(0, 0, 0, 0.22);\n  pointer-events: none;\n}\n\n/* Horizontal + vertical gradients for gloss and curvature */\n.card::after {\n  content: \"\";\n  position: absolute;\n  inset: 0;\n  z-index: 4;\n  border-radius: inherit;\n  background:\n    linear-gradient(90deg, rgba(255, 255, 255, 0.18), transparent 18% 78%, rgba(0, 0, 0, 0.18)),\n    linear-gradient(180deg, rgba(255, 255, 255, 0.06), transparent 35%, rgba(0, 0, 0, 0.14));\n  opacity: 0.72;\n  pointer-events: none;\n}\n\n.video,\n.image {\n  display: block;\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  object-position: 50% 50%;\n  border-radius: inherit;\n  background: transparent;\n}\n\n.image {\n  -webkit-user-drag: none;\n}\n\n/* Media-free placeholder card */\n.placeholder {\n  display: grid;\n  place-items: center;\n  width: 100%;\n  height: 100%;\n  border-radius: inherit;\n}\n\n.placeholderIndex {\n  font-size: clamp(28px, 3.2vw, 52px);\n  font-weight: 700;\n  color: rgba(255, 255, 255, 0.4);\n  font-variant-numeric: tabular-nums;\n}\n\n.dragging {\n  cursor: grabbing;\n}\n\n/* ------------------------------------------------------------------\n   Drag hint below the center card: a decorative toggle whose knob\n   slides left→right in a loop — \"this ring can be scrolled/dragged\".\n   Purely an affordance; it is not an on/off switch.\n   ------------------------------------------------------------------ */\n.scrollHint {\n  position: absolute;\n  left: 50%;\n  top: calc(50% + var(--pov-hint-offset));\n  transform: translateX(-50%);\n  z-index: 5;\n  display: flex;\n  align-items: center;\n  gap: 9px;\n  pointer-events: none;\n}\n\n.toggle {\n  position: relative;\n  width: 54px;\n  height: 26px;\n  border-radius: 999px;\n  background: rgba(255, 255, 255, 0.14);\n  border: 1px solid rgba(255, 255, 255, 0.18);\n  box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.2);\n  backdrop-filter: blur(6px);\n}\n\n.knob {\n  position: absolute;\n  top: 50%;\n  left: 4px;\n  width: 18px;\n  height: 18px;\n  border-radius: 50%;\n  background: rgba(255, 255, 255, 0.85);\n  transform: translate(0, -50%);\n  animation: povKnobDrag 1.8s ease-in-out infinite;\n}\n\n@keyframes povKnobDrag {\n  0% {\n    transform: translate(0, -50%);\n    opacity: 0;\n  }\n  14% {\n    opacity: 1;\n  }\n  68% {\n    transform: translate(28px, -50%);\n    opacity: 1;\n  }\n  86% {\n    transform: translate(28px, -50%);\n    opacity: 0;\n  }\n  100% {\n    transform: translate(0, -50%);\n    opacity: 0;\n  }\n}\n\n.chevron {\n  width: 16px;\n  height: 16px;\n  color: rgba(255, 255, 255, 0.55);\n  animation: povChevronNudge 1.8s ease-in-out infinite;\n}\n\n@keyframes povChevronNudge {\n  0%,\n  100% {\n    transform: translateX(0);\n    opacity: 0.5;\n  }\n  60% {\n    transform: translateX(2px);\n    opacity: 0.95;\n  }\n}\n\n/* ------------------------------------------------------------------\n   Responsive: shrink radius/cards so the ring never breaks\n   ------------------------------------------------------------------ */\n@media (max-width: 1024px) {\n  .carousel {\n    --pov-radius: clamp(560px, 60vw, 860px);\n    --pov-card-w: clamp(230px, 24vw, 320px);\n  }\n}\n\n/* Mobile: center + one card each side fits cleanly */\n@media (max-width: 760px) {\n  .carousel {\n    width: 100%;\n    min-height: 0;\n    height: min(54vh, 284px);\n    --pov-shift-y: -22px;\n    --pov-perspective: clamp(780px, 300vw, 1500px);\n    --pov-radius: clamp(360px, 110vw, 620px);\n    --pov-card-w: clamp(160px, 42vw, 230px);\n    --pov-card-h: calc(var(--pov-card-w) * 1.46);\n    --pov-hint-offset: 88px;\n  }\n\n  .scrollHint {\n    transform: translateX(-50%) scale(0.8);\n  }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .carousel {\n    cursor: default;\n  }\n  /* Auto-rotation (the large motion) is disabled by the rAF loop under\n     reduced motion. The drag hint deliberately keeps animating: it IS\n     the signal that the ring can be scrolled, and Windows' \"show\n     animations\" toggle maps to this media query — killing it here left\n     the hint frozen for those users. */\n}\n",
